  "risk": {
    "level": "high",
    "touches": [
      "p2p"
    ],
    "why": "Flaws in compact block generation, transaction indexing, or platform-specific TCP socket querying could stall block propagation, cause peer desynchronization, or crash network threads across different operating systems."
  }
